e polissage, étape par étape."}, {"image": null, "alt": "La vitrine de la boutique éclairée le soir.", "caption": "La boutique, ouverte du mardi au samedi."}]}","template":"<section class="text-gallery text-gallery--{{ props.layout|default('photos-right') }}"><div class="text-gallery__content">{% if props.title is not empty %}<h2 class="text-gallery__title">{{ props.title }}</h2>{% endif %}{% if props.text is not empty %}<div class="text-gallery__text">{{ props.text }}</div>{% endif %}{% if props.button_label is not empty and props.button_url is not empty %}<p class="text-gallery__action"><a class="text-gallery__button" href="{{ props.button_url }}">{{ props.button_label }}</a></p>{% endif %}</div>{% if props.photos is not empty %}<ul class="text-gallery__track" tabindex="0"{% if props.gallery_label is not empty %} aria-label="{{ props.gallery_label }}"{% endif %} data-cms-sizes="(min-width: 48rem) 40vw, 85vw">{% for photo in props.photos %}{% if photo.image %}<li class="text-gallery__slide"><figure class="text-gallery__figure"><img class="text-gallery__image" src="{{ photo.image }}" alt="{{ photo.alt|default('') }}">{% if photo.caption is not empty %}<figcaption class="text-gallery__caption">{{ photo.caption }}</figcaption>{% endif %}</figure></li>{% endif %}{% endfor %}</ul>{% endif %}</section>","css":":scope .text-gallery { display: grid; gap: 2rem; align-items: center; }
.text-gallery__title { margin: 0 0 1rem; }
.text-gallery__text { color: var(--cms-color-text-muted); }
.text-gallery__action { margin: 1.5rem 0 0; }
.text-gallery__button { display: inline-block; padding: 0.75rem 1.5rem; border-radius: 0.375rem; background: var(--cms-color-accent); color: var(--cms-color-on-accent); text-decoration: none; transition: background-color 0.2s ease; }
.text-gallery__button:hover { background: var(--cms-color-accent-strong); }
.text-gallery__button:focus-visible { background: var(--cms-color-accent-strong); outline: 2px solid var(--cms-color-accent); outline-offset: 2px; }
.text-gallery__track { display: flex; gap: 1rem; margin: 0; padding: 0 0 0.75rem; list-style: none; overflow-x: auto; scroll-snap-type: x mandatory; overscroll-behavior-x: contain; min-width: 0; }
.text-gallery__track:focus-visible { outline: 2px solid var(--cms-color-accent); outline-offset: 4px; }
.text-gallery__slide { flex: 0 0 88%; scroll-snap-align: start; }
.text-gallery__figure { margin: 0; }
.text-gallery__image { display: block; width: 100%; height: auto; aspect-ratio: 4 / 3; object-fit: cover; border-radius: 0.5rem; background: var(--cms-color-accent-surface); }
.text-gallery__caption { margin-top: 0.5rem; font-size: 0.875rem; color: var(--cms-color-text-subtle); }
@media (min-width: 48rem) { .text-gallery { grid-template-columns: 1fr 1fr; gap: 3rem; } .text-gallery--photos-left .text-gallery__track { order: -1; } }"}

